    title: "「魔の7歳」の事故ピークは5月——GW明けに親子で確認したい通学路の5つの危険ポイント",
    excerpt: "警察庁の最新データによると、歩行中に交通事故で死傷する小学生のうち1年生は6年生の約2.5倍。新1年生の事故は学校生活に慣れ始める5月中旬から下旬にかけて第1のピークを迎えます。GW明けに親子で通学路を歩き直し、危険ポイントを確認するベストタイミングです。",
